contracts/InsurancePolicy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {DriverRegistry} from "./DriverRegistry.sol";
import {SafetyScoreOracle} from "./SafetyScoreOracle.sol";
import {InsurancePool} from "./InsurancePool.sol";
import {InsuranceTypes} from "./libraries/InsuranceTypes.sol";
import {InsuranceEvents} from "./libraries/InsuranceEvents.sol";
import "./libraries/InsuranceErrors.sol";

/**
 * @title InsurancePolicy
 * @author Senior Solidity Architect
 * @notice Manages the insurance policy lifecycle (purchase, renew, cancel,
 *         premium updates) and applies the deterministic safety-score-based
 *         premium adjustment. Reads verified scores from SafetyScoreOracle
 *         and links purchased policies into DriverRegistry — it performs NO
 *         AI computation itself; scoring is entirely off-chain, this
 *         contract only applies a fixed, auditable pricing formula to a
 *         verified score.
 * @dev Off-chain actuarial pricing (the "base premium" for a given coverage
 *      amount) is computed by the backend and passed in at purchase/renewal
 *      time; this contract's only on-chain pricing responsibility is the
 *      deterministic tier adjustment below:
 *
 *        Score 90-100  => 20% discount  (80% of base premium)
 *        Score 75-89   => normal premium (100% of base premium)
 *        Score 60-74   => 10% surcharge (110% of base premium)
 *        Score 0-59    => normal premium, policy flagged `underReview`
 *
 *      Role model:
 *      - DEFAULT_ADMIN_ROLE: grants/revokes roles below; multisig/timelock
 *        in production.
 *      - PAUSER_ROLE: may pause/unpause this contract in an emergency.
 *      - INSURANCE_COMPANY_ROLE: may administratively update a policy's
 *        premium and force-cancel policies (e.g. fraud response).
 *
 *      This contract must itself hold POLICY_MANAGER_ROLE on DriverRegistry
 *      to call `linkPolicy`, granted post-deployment by the DriverRegistry
 *      admin (see deploy.js).
 */
contract InsurancePolicy is AccessControl, Pausable, ReentrancyGuard {
    // ---------------------------------------------------------------
    //                             ROLES
    // ---------------------------------------------------------------

    /// @notice Allowed to pause/unpause this contract in an emergency.
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Allowed to administratively update premiums and force-cancel policies.
    bytes32 public constant INSURANCE_COMPANY_ROLE = keccak256("INSURANCE_COMPANY_ROLE");

    // ---------------------------------------------------------------
    //                           CONSTANTS
    // ---------------------------------------------------------------

    /// @notice Fixed policy term applied on every purchase/renewal.
    uint64 public constant POLICY_DURATION = 365 days;

    /// @notice Basis-point denominator used for premium multiplier math.
    uint256 private constant BPS_DENOMINATOR = 10_000;

    /// @notice 80% of base premium => a 20% discount (score 90-100).
    uint256 private constant DISCOUNT_MULTIPLIER_BPS = 8_000;

    /// @notice 110% of base premium => a 10% surcharge (score 60-74).
    uint256 private constant SURCHARGE_MULTIPLIER_BPS = 11_000;

    /// @notice Safety score threshold at/above which a policy is normal (no surcharge).
    uint8 private constant SCORE_NORMAL_MIN = 75;

    /// @notice Safety score threshold at/above which a policy earns a discount.
    uint8 private constant SCORE_DISCOUNT_MIN = 90;

    /// @notice Safety score threshold at/above which no review is triggered.
    uint8 private constant SCORE_REVIEW_MIN = 60;

    // ---------------------------------------------------------------
    //                       IMMUTABLE DEPENDENCIES
    // ---------------------------------------------------------------

    /// @notice The DriverRegistry this contract links purchased policies into.
    DriverRegistry public immutable driverRegistry;

    /// @notice The SafetyScoreOracle this contract reads verified scores from.
    SafetyScoreOracle public immutable safetyScoreOracle;

    /// @notice The InsurancePool that receives forwarded premium payments.
    InsurancePool public immutable insurancePool;

    // ---------------------------------------------------------------
    //                            STORAGE
    // ---------------------------------------------------------------

    /// @notice policyId => Policy record.
    mapping(uint256 => InsuranceTypes.Policy) private _policies;

    /// @notice Monotonically increasing counter for the next policy ID to assign.
    /// @dev Starts at 1 so that 0 can safely mean "no policy" throughout the protocol.
    uint256 private _nextPolicyId = 1;

    // ---------------------------------------------------------------
    //                          CONSTRUCTOR
    // ---------------------------------------------------------------

    /**
     * @param admin The address to receive DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     * @param driverRegistry_ Deployed DriverRegistry contract address.
     * @param safetyScoreOracle_ Deployed SafetyScoreOracle contract address.
     * @param insurancePool_ Deployed InsurancePool contract address.
     */
    constructor(address admin, address driverRegistry_, address safetyScoreOracle_, address insurancePool_) {
        if (admin == address(0)) revert ZeroAddress();
        if (driverRegistry_ == address(0)) revert ZeroAddress();
        if (safetyScoreOracle_ == address(0)) revert ZeroAddress();
        if (insurancePool_ == address(0)) revert ZeroAddress();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);

        driverRegistry = DriverRegistry(driverRegistry_);
        safetyScoreOracle = SafetyScoreOracle(safetyScoreOracle_);
        insurancePool = InsurancePool(payable(insurancePool_));
    }

    // ---------------------------------------------------------------
    //                       POLICY LIFECYCLE
    // ---------------------------------------------------------------

    /**
     * @notice Purchases a new insurance policy for the caller.
     * @dev `basePremium` is the off-chain-computed actuarial premium for
     *      `coverageAmount`, supplied by the backend/frontend; this function
     *      applies the deterministic score-tier adjustment on top of it and
     *      requires exact payment of the resulting amount. Reverts if the
     *      caller is not a registered driver, already holds an active
     *      policy, or sends the wrong ETH amount. Forwards payment to
     *      InsurancePool and links the new policy into DriverRegistry.
     * @param basePremium The off-chain-computed base premium, in wei, before
     *                     the safety-score adjustment.
     * @param coverageAmount The maximum payout coverage for this policy, in wei.
     * @return policyId The newly created policy ID.
     */
    function purchasePolicy(
        uint256 basePremium,
        uint256 coverageAmount
    ) external payable whenNotPaused nonReentrant returns (uint256 policyId) {
        if (basePremium == 0) revert ZeroAmount();
        if (coverageAmount == 0) revert ZeroAmount();
        if (!driverRegistry.isRegistered(msg.sender)) revert DriverNotRegistered(msg.sender);

        InsuranceTypes.Driver memory driver = driverRegistry.getDriver(msg.sender);
        if (driver.policyId != 0 && _isActive(_policies[driver.policyId])) {
            revert PolicyAlreadyActive(msg.sender);
        }

        uint8 score = safetyScoreOracle.latestScore(msg.sender);
        (uint256 finalPremium, bool underReview) = _calculatePremium(basePremium, score);

        if (msg.value != finalPremium) revert IncorrectPremiumAmount(finalPremium, msg.value);

        policyId = _nextPolicyId++;
        uint64 startTime = uint64(block.timestamp);
        uint64 expiryTime = startTime + POLICY_DURATION;

        _policies[policyId] = InsuranceTypes.Policy({
            id: policyId,
            driver: msg.sender,
            premium: finalPremium,
            coverage: coverageAmount,
            startTime: startTime,
            expiryTime: expiryTime,
            active: true,
            underReview: underReview
        });

        // Effects are complete before external interactions below.
        driverRegistry.linkPolicy(msg.sender, policyId);
        insurancePool.deposit{value: msg.value}();

        emit InsuranceEvents.PolicyPurchased(policyId, msg.sender, finalPremium, coverageAmount, expiryTime);
    }

    /**
     * @notice Renews an existing policy for another full term.
     * @dev Only the policy's driver may renew it. Re-applies the current
     *      safety-score tier to the newly supplied base premium. Resets
     *      `startTime`/`expiryTime` to a fresh 365-day term and reactivates
     *      the policy (including clearing a prior `underReview` flag if the
     *      score has since improved).
     * @param policyId The policy ID to renew.
     * @param newBasePremium The off-chain-computed base premium for the
     *                        renewal term, in wei, before score adjustment.
     */
    function renewPolicy(uint256 policyId, uint256 newBasePremium) external payable whenNotPaused nonReentrant {
        InsuranceTypes.Policy storage policy = _policies[policyId];
        if (policy.driver == address(0)) revert PolicyNotFound(policyId);
        if (policy.driver != msg.sender) revert NotPolicyOwner(msg.sender, policyId);
        if (newBasePremium == 0) revert ZeroAmount();

        uint8 score = safetyScoreOracle.latestScore(msg.sender);
        (uint256 finalPremium, bool underReview) = _calculatePremium(newBasePremium, score);

        if (msg.value != finalPremium) revert IncorrectPremiumAmount(finalPremium, msg.value);

        uint64 startTime = uint64(block.timestamp);
        uint64 expiryTime = startTime + POLICY_DURATION;

        policy.premium = finalPremium;
        policy.startTime = startTime;
        policy.expiryTime = expiryTime;
        policy.active = true;
        policy.underReview = underReview;

        insurancePool.deposit{value: msg.value}();

        emit InsuranceEvents.PolicyRenewed(policyId, finalPremium, expiryTime);
    }

    /**
     * @notice Cancels a policy, immediately ending coverage.
     * @dev Callable by the policy's driver, or by an INSURANCE_COMPANY_ROLE
     *      holder (e.g. fraud response / regulatory action). No premium
     *      refund logic is applied — out of scope for this lean build.
     * @param policyId The policy ID to cancel.
     */
    function cancelPolicy(uint256 policyId) external whenNotPaused {
        InsuranceTypes.Policy storage policy = _policies[policyId];
        if (policy.driver == address(0)) revert PolicyNotFound(policyId);
        if (msg.sender != policy.driver && !hasRole(INSURANCE_COMPANY_ROLE, msg.sender)) {
            revert NotPolicyOwner(msg.sender, policyId);
        }

        policy.active = false;

        emit InsuranceEvents.PolicyCancelled(policyId, msg.sender);
    }

    /**
     * @notice Administratively overrides a policy's stored premium value.
     * @dev Restricted to INSURANCE_COMPANY_ROLE. This is a bookkeeping
     *      override (e.g. correcting a pricing error) and does NOT collect
     *      or refund any ETH — it only updates the recorded premium amount.
     * @param policyId The policy ID to update.
     * @param newPremium The corrected premium amount, in wei.
     */
    function updatePremium(
        uint256 policyId,
        uint256 newPremium
    ) external onlyRole(INSURANCE_COMPANY_ROLE) whenNotPaused {
        InsuranceTypes.Policy storage policy = _policies[policyId];
        if (policy.driver == address(0)) revert PolicyNotFound(policyId);

        uint256 oldPremium = policy.premium;
        policy.premium = newPremium;

        emit InsuranceEvents.PremiumUpdated(policyId, oldPremium, newPremium);
    }

    // ---------------------------------------------------------------
    //                        VIEW FUNCTIONS
    // ---------------------------------------------------------------

    /**
     * @notice Returns whether a policy is currently active.
     * @dev Lazy-expiry check: a policy is active only if its `active` flag
     *      is set AND the current block timestamp has not passed its
     *      `expiryTime`. No state transition transaction is required for a
     *      policy to be treated as expired.
     * @param policyId The policy ID to check.
     * @return active True if the policy is in force right now.
     */
    function isPolicyActive(uint256 policyId) external view returns (bool active) {
        return _isActive(_policies[policyId]);
    }

    /**
     * @notice Returns the full on-chain record for a policy.
     * @dev Reverts with `PolicyNotFound` if `policyId` does not exist.
     * @param policyId The policy ID to look up.
     * @return policy The `InsuranceTypes.Policy` record.
     */
    function getPolicy(uint256 policyId) external view returns (InsuranceTypes.Policy memory policy) {
        if (_policies[policyId].driver == address(0)) revert PolicyNotFound(policyId);
        return _policies[policyId];
    }

    // ---------------------------------------------------------------
    //                        EMERGENCY CONTROL
    // ---------------------------------------------------------------

    /// @notice Pauses purchase, renewal, cancellation, and premium updates.
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit InsuranceEvents.EmergencyPaused(msg.sender);
    }

    /// @notice Resumes normal operation after a pause.
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
        emit InsuranceEvents.EmergencyUnpaused(msg.sender);
    }

    // ---------------------------------------------------------------
    //                        INTERNAL HELPERS
    // ---------------------------------------------------------------

    /**
     * @dev Applies the fixed safety-score premium tiers to a base premium.
     *      Pure function — takes the score as input rather than reading
     *      the oracle itself, keeping it independently testable.
     * @param basePremium The off-chain-computed base premium, in wei.
     * @param score The driver's latest verified safety score (0-100).
     * @return finalPremium The premium after tier adjustment, in wei.
     * @return underReview True if the score is below the review threshold (<60).
     */
    function _calculatePremium(
        uint256 basePremium,
        uint8 score
    ) internal pure returns (uint256 finalPremium, bool underReview) {
        if (score >= SCORE_DISCOUNT_MIN) {
            finalPremium = (basePremium * DISCOUNT_MULTIPLIER_BPS) / BPS_DENOMINATOR;
        } else if (score >= SCORE_NORMAL_MIN) {
            finalPremium = basePremium;
        } else if (score >= SCORE_REVIEW_MIN) {
            finalPremium = (basePremium * SURCHARGE_MULTIPLIER_BPS) / BPS_DENOMINATOR;
        } else {
            finalPremium = basePremium;
            underReview = true;
        }
    }

    /// @dev A policy is active iff its flag is set and it has not yet expired.
    function _isActive(InsuranceTypes.Policy storage policy) internal view returns (bool) {
        return policy.active && block.timestamp <= policy.expiryTime;
    }
}

contracts/DriverRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

import {InsuranceTypes} from "./libraries/InsuranceTypes.sol";
import {InsuranceEvents} from "./libraries/InsuranceEvents.sol";
import "./libraries/InsuranceErrors.sol";

/**
 * @title DriverRegistry
 * @author Senior Solidity Architect
 * @notice Minimal on-chain link between a wallet, an off-chain driver
 *         identity, and an active policy ID. Stores nothing else — trip
 *         history, AI inputs, documents, and telemetry all live off-chain
 *         in the backend, per project scope.
 * @dev `driverId` is a bytes32 handle minted off-chain (e.g. a hash of a
 *      backend UUID) and passed in at registration time; this contract does
 *      not generate identity, it only anchors it on-chain and prevents a
 *      wallet from registering twice.
 *
 *      Role model:
 *      - DEFAULT_ADMIN_ROLE: grants/revokes all roles below; should be a
 *        multisig/timelock in production, not an EOA.
 *      - PAUSER_ROLE: may pause/unpause this contract in an emergency.
 *      - POLICY_MANAGER_ROLE: granted exclusively to the deployed
 *        InsurancePolicy contract address, allowing it (and only it) to
 *        link a policy ID to a driver once a policy is purchased.
 */
contract DriverRegistry is AccessControl, Pausable {
    // ---------------------------------------------------------------
    //                             ROLES
    // ---------------------------------------------------------------

    /// @notice Allowed to pause/unpause this contract in an emergency.
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Granted exclusively to the InsurancePolicy contract address,
    ///         allowing it to link a purchased policy ID to a driver record.
    bytes32 public constant POLICY_MANAGER_ROLE = keccak256("POLICY_MANAGER_ROLE");

    // ---------------------------------------------------------------
    //                            STORAGE
    // ---------------------------------------------------------------

    /// @notice wallet => Driver record.
    mapping(address => InsuranceTypes.Driver) private _drivers;

    // ---------------------------------------------------------------
    //                          CONSTRUCTOR
    // ---------------------------------------------------------------

    /**
     * @param admin The address to receive DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     *              In production this should be a multisig or timelock.
     */
    constructor(address admin) {
        if (admin == address(0)) revert ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    // ---------------------------------------------------------------
    //                       DRIVER REGISTRATION
    // ---------------------------------------------------------------

    /**
     * @notice Registers the caller's wallet as a driver, linked to an
     *         off-chain-assigned driver identifier.
     * @dev Self-service only: a wallet can register itself, but nothing else
     *      can register on its behalf, since driver identity is tied 1:1 to
     *      the wallet signing the transaction. Reverts with
     *      `DriverAlreadyRegistered` if the caller has already registered.
     * @param driverId The off-chain-assigned driver identifier (e.g. a hash
     *                  of a backend UUID) to anchor on-chain.
     */
    function registerDriver(bytes32 driverId) external whenNotPaused {
        if (_drivers[msg.sender].registered) revert DriverAlreadyRegistered(msg.sender);
        if (driverId == bytes32(0)) revert ZeroAmount();

        _drivers[msg.sender] = InsuranceTypes.Driver({
            wallet: msg.sender,
            driverId: driverId,
            policyId: 0,
            registered: true
        });

        emit InsuranceEvents.DriverRegistered(msg.sender, driverId);
    }

    // ---------------------------------------------------------------
    //                        VIEW FUNCTIONS
    // ---------------------------------------------------------------

    /**
     * @notice Returns the on-chain driver record for a wallet.
     * @dev Reverts with `DriverNotRegistered` if the wallet never registered.
     * @param wallet The wallet address to look up.
     * @return driver The wallet's `InsuranceTypes.Driver` record.
     */
    function getDriver(address wallet) external view returns (InsuranceTypes.Driver memory driver) {
        if (!_drivers[wallet].registered) revert DriverNotRegistered(wallet);
        return _drivers[wallet];
    }

    /**
     * @notice Returns whether a wallet is registered as a driver.
     * @param wallet The wallet address to check.
     * @return registered True if the wallet has an associated driver record.
     */
    function isRegistered(address wallet) external view returns (bool registered) {
        return _drivers[wallet].registered;
    }

    // ---------------------------------------------------------------
    //              STATE WRITES — RESTRICTED TO TRUSTED CONTRACTS
    // ---------------------------------------------------------------

    /**
     * @notice Links a purchased policy ID to a driver's wallet.
     * @dev Restricted to POLICY_MANAGER_ROLE (the InsurancePolicy contract).
     *      Reverts with `DriverNotRegistered` if the wallet is not registered.
     * @param wallet The driver's wallet address.
     * @param policyId The policy ID to associate with this driver.
     */
    function linkPolicy(address wallet, uint256 policyId) external onlyRole(POLICY_MANAGER_ROLE) whenNotPaused {
        if (!_drivers[wallet].registered) revert DriverNotRegistered(wallet);
        _drivers[wallet].policyId = policyId;
    }

    // ---------------------------------------------------------------
    //                        EMERGENCY CONTROL
    // ---------------------------------------------------------------

    /// @notice Pauses all state-mutating functions on this contract.
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit InsuranceEvents.EmergencyPaused(msg.sender);
    }

    /// @notice Resumes normal operation after a pause.
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
        emit InsuranceEvents.EmergencyUnpaused(msg.sender);
    }
}

contracts/libraries/InsuranceTypes.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/**
 * @title InsuranceTypes
 * @author Senior Solidity Architect
 * @notice Minimal, shared struct definitions for the Driver Insurance
 *         protocol. Only the fields strictly required for trustless
 *         on-chain insurance logic live here — everything else (trip
 *         history, AI inputs, documents, telemetry, driver profiles) is
 *         intentionally kept off-chain in the backend, per project scope.
 * @dev Pure type definitions only: no storage, no functions, no external
 *      calls. Imported by every contract so all modules agree on layout.
 */
library InsuranceTypes {
    /**
     * @notice Minimal on-chain driver identity record.
     * @dev `driverId` is a bytes32 handle (e.g. keccak256 of an off-chain
     *      UUID or backend record ID) rather than a sequential uint256 —
     *      this lets the backend mint IDs however it likes without the
     *      chain needing to be the source of ID generation.
     */
    struct Driver {
        address wallet;
        bytes32 driverId;
        uint256 policyId;
        bool registered;
    }

    /**
     * @notice Minimal on-chain insurance policy record.
     * @dev `underReview` is a small necessary addition beyond the literal
     *      spec list: the premium-logic requirement ("Below 60: Mark policy
     *      for review") needs somewhere durable to persist that state so
     *      ClaimManager can block claims on policies pending review. It costs
     *      one extra bit, packed into the same slot as `active` (both are
     *      bool, 1 byte each) — zero extra storage slots.
     */
    struct Policy {
        uint256 id;
        address driver;
        uint256 premium;
        uint256 coverage;
        uint64 startTime;
        uint64 expiryTime;
        bool active;
        bool underReview;
    }

    /**
     * @notice Minimal on-chain insurance claim record.
     */
    struct Claim {
        uint256 id;
        uint256 policyId;
        uint256 amount;
        bool submitted;
        bool accidentVerified;
        bool approved;
        bool paid;
    }
}

contracts/libraries/InsuranceEvents.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/**
 * @title InsuranceEvents
 * @author Senior Solidity Architect
 * @notice Centralized event definitions for the lean Driver Insurance protocol.
 * @dev Events declared inside a library can be emitted directly by any
 *      contract that imports it, via `InsuranceEvents.EventName(...)` — one
 *      canonical definition instead of duplicating identical events across
 *      DriverRegistry, InsurancePolicy, ClaimManager, and InsurancePool.
 */
library InsuranceEvents {
    /// @notice Emitted when a new driver registers with the platform.
    /// @param wallet The driver's wallet address.
    /// @param driverId The off-chain-assigned driver identifier.
    event DriverRegistered(address indexed wallet, bytes32 driverId);

    /// @notice Emitted when a driver purchases a new insurance policy.
    /// @param policyId The newly created policy ID.
    /// @param driver The driver the policy belongs to.
    /// @param premium The premium paid, in wei.
    /// @param coverage The maximum payout coverage, in wei.
    /// @param expiryTime The unix timestamp the policy expires.
    event PolicyPurchased(
        uint256 indexed policyId,
        address indexed driver,
        uint256 premium,
        uint256 coverage,
        uint64 expiryTime
    );

    /// @notice Emitted when a policy is renewed.
    /// @param policyId The renewed policy ID.
    /// @param newPremium The updated premium, in wei.
    /// @param newExpiryTime The new expiry timestamp.
    event PolicyRenewed(uint256 indexed policyId, uint256 newPremium, uint64 newExpiryTime);

    /// @notice Emitted when a policy is cancelled by the driver or the insurer.
    /// @param policyId The cancelled policy ID.
    /// @param cancelledBy The address that initiated the cancellation.
    event PolicyCancelled(uint256 indexed policyId, address indexed cancelledBy);

    /// @notice Emitted whenever a policy's premium amount is recalculated or updated.
    /// @param policyId The affected policy ID.
    /// @param oldPremium The previous premium, in wei.
    /// @param newPremium The new premium, in wei.
    event PremiumUpdated(uint256 indexed policyId, uint256 oldPremium, uint256 newPremium);

    /// @notice Emitted when the oracle submits an updated safety score for a driver.
    /// @param driver The driver wallet whose score was updated.
    /// @param newScore The new safety score (0-100).
    event SafetyScoreUpdated(address indexed driver, uint8 newScore);

    /// @notice Emitted when a driver submits a new claim.
    /// @param claimId The newly created claim ID.
    /// @param policyId The policy the claim is filed against.
    /// @param amount The amount requested, in wei.
    event ClaimSubmitted(uint256 indexed claimId, uint256 indexed policyId, uint256 amount);

    /// @notice Emitted when the insurance company approves a claim for payout.
    /// @param claimId The approved claim ID.
    /// @param approvedBy The insurance-company address that approved it.
    event ClaimApproved(uint256 indexed claimId, address indexed approvedBy);

    /// @notice Emitted when a claim is rejected.
    /// @param claimId The rejected claim ID.
    /// @param reason A short human-readable reason.
    /// @param rejectedBy The address that rejected the claim.
    event ClaimRejected(uint256 indexed claimId, string reason, address indexed rejectedBy);

    /// @notice Emitted when a claim payout has been successfully transferred to the driver.
    /// @param claimId The paid claim ID.
    /// @param driver The recipient driver wallet.
    /// @param amount The amount paid out, in wei.
    event PayoutCompleted(uint256 indexed claimId, address indexed driver, uint256 amount);

    /// @notice Emitted when funds are deposited into the InsurancePool.
    /// @param depositor The address that deposited funds.
    /// @param amount The amount deposited, in wei.
    event FundsDeposited(address indexed depositor, uint256 amount);

    /// @notice Emitted when a contract is paused in response to an emergency.
    /// @param pausedBy The address that triggered the pause.
    event EmergencyPaused(address indexed pausedBy);

    /// @notice Emitted when a contract is unpaused, resuming normal operations.
    /// @param unpausedBy The address that lifted the pause.
    event EmergencyUnpaused(address indexed unpausedBy);
}

contracts/SafetyScoreOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

import {InsuranceEvents} from "./libraries/InsuranceEvents.sol";
import "./libraries/InsuranceErrors.sol";

/**
 * @title SafetyScoreOracle
 * @author Senior Solidity Architect
 * @notice Stores the latest AI-generated driver safety score, submitted by
 *         a trusted off-chain oracle backend. Performs NO score computation
 *         on-chain — it is a verified-value store, nothing more.
 * @dev Intentionally decoupled from DriverRegistry: this contract does not
 *      check whether an address is a registered driver before accepting a
 *      score. That validation belongs to whichever contract consumes the
 *      score (InsurancePolicy), keeping this oracle a simple, standalone,
 *      easily-swappable component — exactly the "store only the minimum
 *      verifiable state" scope requested.
 *
 *      Role model:
 *      - DEFAULT_ADMIN_ROLE: grants/revokes roles below; should be a
 *        multisig/timelock in production.
 *      - PAUSER_ROLE: may pause/unpause this contract in an emergency.
 *      - ORACLE_ROLE: held by the trusted off-chain oracle backend
 *        wallet(s); the only accounts permitted to submit scores.
 */
contract SafetyScoreOracle is AccessControl, Pausable {
    // ---------------------------------------------------------------
    //                             ROLES
    // ---------------------------------------------------------------

    /// @notice Allowed to pause/unpause this contract in an emergency.
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Allowed to submit AI-generated safety scores. Held by the
    ///         off-chain oracle backend wallet(s).
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    // ---------------------------------------------------------------
    //                            STORAGE
    // ---------------------------------------------------------------

    /// @notice driver wallet => most recent verified safety score (0-100).
    /// @dev Public mapping auto-generates a `latestScore(address) view
    ///      returns (uint8)` getter, satisfying the "store only this
    ///      mapping" requirement without a redundant wrapper function.
    mapping(address => uint8) public latestScore;

    // ---------------------------------------------------------------
    //                          CONSTRUCTOR
    // ---------------------------------------------------------------

    /**
     * @param admin The address to receive DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     *              In production this should be a multisig or timelock.
     *              ORACLE_ROLE is granted separately by the admin after
     *              deployment, to the actual oracle backend address(es).
     */
    constructor(address admin) {
        if (admin == address(0)) revert ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    // ---------------------------------------------------------------
    //                        SCORE SUBMISSION
    // ---------------------------------------------------------------

    /**
     * @notice Submits a new AI-generated safety score for a driver.
     * @dev Restricted to ORACLE_ROLE. Reverts with `InvalidSafetyScore` if
     *      `score` exceeds 100. Overwrites any previous score for `driver` —
     *      only the latest score is kept on-chain, consistent with the
     *      "minimum verifiable state" scope; full score history, if needed,
     *      is the backend's responsibility to log off-chain.
     * @param driver The driver wallet the score applies to.
     * @param score The new safety score, in the range 0-100.
     */
    function submitScore(address driver, uint8 score) external onlyRole(ORACLE_ROLE) whenNotPaused {
        if (driver == address(0)) revert ZeroAddress();
        if (score > 100) revert InvalidSafetyScore(score);

        latestScore[driver] = score;

        emit InsuranceEvents.SafetyScoreUpdated(driver, score);
    }

    // ---------------------------------------------------------------
    //                        EMERGENCY CONTROL
    // ---------------------------------------------------------------

    /// @notice Pauses score submission on this contract.
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit InsuranceEvents.EmergencyPaused(msg.sender);
    }

    /// @notice Resumes normal operation after a pause.
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
        emit InsuranceEvents.EmergencyUnpaused(msg.sender);
    }
}

contracts/InsurancePool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {InsuranceEvents} from "./libraries/InsuranceEvents.sol";
import "./libraries/InsuranceErrors.sol";

/**
 * @title InsurancePool
 * @author Senior Solidity Architect
 * @notice Minimal treasury contract: holds ETH collected from premiums and
 *         insurer top-ups, and pays out approved claims. Added beyond the
 *         original four-contract list because ClaimManager's "automatic
 *         payout transfer" requirement needs funds to live somewhere on-chain
 *         — this contract is intentionally as small as possible: no policy
 *         logic, no claim logic, just custody and controlled disbursement.
 * @dev Role model:
 *      - DEFAULT_ADMIN_ROLE: grants/revokes roles below; multisig/timelock
 *        in production.
 *      - PAUSER_ROLE: may pause/unpause deposits and payouts in an emergency.
 *      - SPENDER_ROLE: granted exclusively to the deployed ClaimManager
 *        contract address, allowing it (and only it) to trigger payouts.
 *      - INSURANCE_COMPANY_ROLE: may fund the pool directly (though anyone
 *        can technically call `deposit`; this role exists for clarity and
 *        matches the top-level spec's "Fund payouts" responsibility).
 */
contract InsurancePool is AccessControl, Pausable, ReentrancyGuard {
    // ---------------------------------------------------------------
    //                             ROLES
    // ---------------------------------------------------------------

    /// @notice Allowed to pause/unpause this contract in an emergency.
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Granted exclusively to the ClaimManager contract address,
    ///         allowing it to trigger payouts from pool funds.
    bytes32 public constant SPENDER_ROLE = keccak256("SPENDER_ROLE");

    /// @notice May deposit funds into the pool (also open to any depositor
    ///         via `deposit`, e.g. InsurancePolicy forwarding premiums).
    bytes32 public constant INSURANCE_COMPANY_ROLE = keccak256("INSURANCE_COMPANY_ROLE");

    // ---------------------------------------------------------------
    //                          CONSTRUCTOR
    // ---------------------------------------------------------------

    /**
     * @param admin The address to receive DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     *              In production this should be a multisig or timelock.
     */
    constructor(address admin) {
        if (admin == address(0)) revert ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    // ---------------------------------------------------------------
    //                            DEPOSITS
    // ---------------------------------------------------------------

    /**
     * @notice Deposits native ETH into the pool.
     * @dev Open to any caller — used both for insurer top-ups
     *      (INSURANCE_COMPANY_ROLE holders) and for InsurancePolicy
     *      forwarding collected premiums. Reverts with `ZeroAmount` if no
     *      ETH is attached.
     */
    function deposit() external payable whenNotPaused {
        if (msg.value == 0) revert ZeroAmount();
        emit InsuranceEvents.FundsDeposited(msg.sender, msg.value);
    }

    /// @dev Allows the pool to receive plain ETH transfers (e.g. `send`/`transfer`)
    ///      as an additional funding path, treated identically to `deposit()`.
    receive() external payable {
        if (msg.value == 0) revert ZeroAmount();
        emit InsuranceEvents.FundsDeposited(msg.sender, msg.value);
    }

    // ---------------------------------------------------------------
    //                            PAYOUTS
    // ---------------------------------------------------------------

    /**
     * @notice Pays out an approved claim amount to a driver's wallet.
     * @dev Restricted to SPENDER_ROLE (the ClaimManager contract).
     *      Follows checks-effects-interactions: the balance check happens
     *      before the external call, and `nonReentrant` guards against
     *      reentrancy during the ETH transfer. Reverts with
     *      `InsufficientPoolBalance` if funds are short, and
     *      `TransferFailed` if the low-level call fails.
     * @param to The driver wallet receiving the payout.
     * @param amount The amount to pay out, in wei.
     * @return success True if the payout transfer succeeded.
     */
    function payOut(
        address payable to,
        uint256 amount
    ) external onlyRole(SPENDER_ROLE) whenNotPaused nonReentrant returns (bool success) {
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (amount > address(this).balance) revert InsufficientPoolBalance(amount, address(this).balance);

        (bool sent, ) = to.call{value: amount}("");
        if (!sent) revert TransferFailed(to, amount);

        return true;
    }

    // ---------------------------------------------------------------
    //                        VIEW FUNCTIONS
    // ---------------------------------------------------------------

    /// @notice Returns the pool's current ETH balance.
    /// @return balance The pool's balance, in wei.
    function getPoolBalance() external view returns (uint256 balance) {
        return address(this).balance;
    }

    // ---------------------------------------------------------------
    //                        EMERGENCY CONTROL
    // ---------------------------------------------------------------

    /// @notice Pauses deposits and payouts on this contract.
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit InsuranceEvents.EmergencyPaused(msg.sender);
    }

    /// @notice Resumes normal operation after a pause.
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
        emit InsuranceEvents.EmergencyUnpaused(msg.sender);
    }
}

contracts/DriverRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

import {InsuranceTypes} from "./libraries/InsuranceTypes.sol";
import {InsuranceEvents} from "./libraries/InsuranceEvents.sol";
import "./libraries/InsuranceErrors.sol";

/**
 * @title DriverRegistry
 * @author Senior Solidity Architect
 * @notice Minimal on-chain link between a wallet, an off-chain driver
 *         identity, and an active policy ID. Stores nothing else — trip
 *         history, AI inputs, documents, and telemetry all live off-chain
 *         in the backend, per project scope.
 * @dev `driverId` is a bytes32 handle minted off-chain (e.g. a hash of a
 *      backend UUID) and passed in at registration time; this contract does
 *      not generate identity, it only anchors it on-chain and prevents a
 *      wallet from registering twice.
 *
 *      Role model:
 *      - DEFAULT_ADMIN_ROLE: grants/revokes all roles below; should be a
 *        multisig/timelock in production, not an EOA.
 *      - PAUSER_ROLE: may pause/unpause this contract in an emergency.
 *      - POLICY_MANAGER_ROLE: granted exclusively to the deployed
 *        InsurancePolicy contract address, allowing it (and only it) to
 *        link a policy ID to a driver once a policy is purchased.
 */
contract DriverRegistry is AccessControl, Pausable {
    // ---------------------------------------------------------------
    //                             ROLES
    // ---------------------------------------------------------------

    /// @notice Allowed to pause/unpause this contract in an emergency.
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Granted exclusively to the InsurancePolicy contract address,
    ///         allowing it to link a purchased policy ID to a driver record.
    bytes32 public constant POLICY_MANAGER_ROLE = keccak256("POLICY_MANAGER_ROLE");

    // ---------------------------------------------------------------
    //                            STORAGE
    // ---------------------------------------------------------------

    /// @notice wallet => Driver record.
    mapping(address => InsuranceTypes.Driver) private _drivers;

    // ---------------------------------------------------------------
    //                          CONSTRUCTOR
    // ---------------------------------------------------------------

    /**
     * @param admin The address to receive DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     *              In production this should be a multisig or timelock.
     */
    constructor(address admin) {
        if (admin == address(0)) revert ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    // ---------------------------------------------------------------
    //                       DRIVER REGISTRATION
    // ---------------------------------------------------------------

    /**
     * @notice Registers the caller's wallet as a driver, linked to an
     *         off-chain-assigned driver identifier.
     * @dev Self-service only: a wallet can register itself, but nothing else
     *      can register on its behalf, since driver identity is tied 1:1 to
     *      the wallet signing the transaction. Reverts with
     *      `DriverAlreadyRegistered` if the caller has already registered.
     * @param driverId The off-chain-assigned driver identifier (e.g. a hash
     *                  of a backend UUID) to anchor on-chain.
     */
    function registerDriver(bytes32 driverId) external whenNotPaused {
        if (_drivers[msg.sender].registered) revert DriverAlreadyRegistered(msg.sender);
        if (driverId == bytes32(0)) revert ZeroAmount();

        _drivers[msg.sender] = InsuranceTypes.Driver({
            wallet: msg.sender,
            driverId: driverId,
            policyId: 0,
            registered: true
        });

        emit InsuranceEvents.DriverRegistered(msg.sender, driverId);
    }

    // ---------------------------------------------------------------
    //                        VIEW FUNCTIONS
    // ---------------------------------------------------------------

    /**
     * @notice Returns the on-chain driver record for a wallet.
     * @dev Reverts with `DriverNotRegistered` if the wallet never registered.
     * @param wallet The wallet address to look up.
     * @return driver The wallet's `InsuranceTypes.Driver` record.
     */
    function getDriver(address wallet) external view returns (InsuranceTypes.Driver memory driver) {
        if (!_drivers[wallet].registered) revert DriverNotRegistered(wallet);
        return _drivers[wallet];
    }

    /**
     * @notice Returns whether a wallet is registered as a driver.
     * @param wallet The wallet address to check.
     * @return registered True if the wallet has an associated driver record.
     */
    function isRegistered(address wallet) external view returns (bool registered) {
        return _drivers[wallet].registered;
    }

    // ---------------------------------------------------------------
    //              STATE WRITES — RESTRICTED TO TRUSTED CONTRACTS
    // ---------------------------------------------------------------

    /**
     * @notice Links a purchased policy ID to a driver's wallet.
     * @dev Restricted to POLICY_MANAGER_ROLE (the InsurancePolicy contract).
     *      Reverts with `DriverNotRegistered` if the wallet is not registered.
     * @param wallet The driver's wallet address.
     * @param policyId The policy ID to associate with this driver.
     */
    function linkPolicy(address wallet, uint256 policyId) external onlyRole(POLICY_MANAGER_ROLE) whenNotPaused {
        if (!_drivers[wallet].registered) revert DriverNotRegistered(wallet);
        _drivers[wallet].policyId = policyId;
    }

    // ---------------------------------------------------------------
    //                        EMERGENCY CONTROL
    // ---------------------------------------------------------------

    /// @notice Pauses all state-mutating functions on this contract.
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit InsuranceEvents.EmergencyPaused(msg.sender);
    }

    /// @notice Resumes normal operation after a pause.
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
        emit InsuranceEvents.EmergencyUnpaused(msg.sender);
    }
}

contracts/libraries/InsuranceErrors.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/**
 * @title InsuranceErrors
 * @author Senior Solidity Architect
 * @notice Centralized, file-level custom errors shared across the lean
 *         Driver Insurance protocol contracts.
 * @dev Declared at file scope (not inside a library/contract) so any
 *      contract can `import` this file and `revert ErrorName(...)` directly.
 *      Custom errors are cheaper than `require(cond, "string")` — a 4-byte
 *      selector + ABI-encoded args instead of a string in bytecode/returndata.
 */

// ---------------------------------------------------------------------
//                      ACCESS CONTROL / GENERAL
// ---------------------------------------------------------------------

/// @notice Thrown when a zero address is passed where a non-zero address is required.
error ZeroAddress();

/// @notice Thrown when a numeric argument is zero but must be non-zero.
error ZeroAmount();

// ---------------------------------------------------------------------
//                          DRIVER REGISTRY
// ---------------------------------------------------------------------

/// @notice Thrown when trying to register a wallet that is already registered.
/// @param wallet The wallet address already on record.
error DriverAlreadyRegistered(address wallet);

/// @notice Thrown when referencing a wallet that has not registered as a driver.
/// @param wallet The unrecognized wallet address.
error DriverNotRegistered(address wallet);

// ---------------------------------------------------------------------
//                          INSURANCE POLICY
// ---------------------------------------------------------------------

/// @notice Thrown when a driver already holds an active policy and tries to purchase another.
/// @param driver The driver wallet with an existing active policy.
error PolicyAlreadyActive(address driver);

/// @notice Thrown when referencing a policy ID that does not exist.
/// @param policyId The unrecognized policy ID.
error PolicyNotFound(uint256 policyId);

/// @notice Thrown when an action requires an active policy but the policy is not active.
/// @param policyId The policy ID in question.
error PolicyNotActive(uint256 policyId);

/// @notice Thrown when an action is attempted on a policy that has expired.
/// @param policyId The expired policy ID.
/// @param expiryTime The timestamp at which the policy expired.
error PolicyExpired(uint256 policyId, uint64 expiryTime);

/// @notice Thrown when the value sent does not match the required premium amount.
/// @param required The expected premium amount in wei.
/// @param sent The amount actually sent in wei.
error IncorrectPremiumAmount(uint256 required, uint256 sent);

/// @notice Thrown when a caller other than the policy's driver attempts a driver-only action.
/// @param caller The address that attempted the action.
/// @param policyId The policy ID they attempted to act on.
error NotPolicyOwner(address caller, uint256 policyId);

/// @notice Thrown when a policy is flagged under review (safety score < 60) and the
///         attempted action requires the policy to be in good standing.
/// @param policyId The policy ID under review.
error PolicyUnderReview(uint256 policyId);

// ---------------------------------------------------------------------
//                        SAFETY SCORE ORACLE
// ---------------------------------------------------------------------

/// @notice Thrown when a submitted safety score is outside the valid 0-100 range.
/// @param score The invalid score that was submitted.
error InvalidSafetyScore(uint8 score);

// ---------------------------------------------------------------------
//                           CLAIM MANAGER
// ---------------------------------------------------------------------

/// @notice Thrown when referencing a claim ID that does not exist.
/// @param claimId The unrecognized claim ID.
error ClaimNotFound(uint256 claimId);

/// @notice Thrown when a driver attempts to submit a new claim while a prior
///         claim on the same policy is still pending resolution.
/// @param policyId The policy ID with a pending claim.
/// @param pendingClaimId The claim ID that is still pending.
error ClaimAlreadyPending(uint256 policyId, uint256 pendingClaimId);

/// @notice Thrown when attempting to verify an accident for a claim that was
///         already verified, or approve/pay a claim not yet in the required state.
/// @param claimId The claim ID.
error InvalidClaimState(uint256 claimId);

/// @notice Thrown when attempting to approve or pay out a claim whose accident
///         has not yet been verified by the oracle.
/// @param claimId The claim ID.
error AccidentNotVerified(uint256 claimId);

/// @notice Thrown when attempting to pay out a claim that has already been paid.
/// @param claimId The claim ID already paid.
error DuplicatePayout(uint256 claimId);

/// @notice Thrown when a claim's requested amount exceeds the policy's coverage amount.
/// @param requested The requested claim amount.
/// @param coverage The policy's maximum coverage amount.
error ClaimExceedsCoverage(uint256 requested, uint256 coverage);

// ---------------------------------------------------------------------
//                          INSURANCE POOL
// ---------------------------------------------------------------------

/// @notice Thrown when the pool's available balance is insufficient to cover a payout.
/// @param requested The requested payout amount.
/// @param available The pool's current available balance.
error InsufficientPoolBalance(uint256 requested, uint256 available);

/// @notice Thrown when a native-token transfer (ETH) fails.
/// @param to The intended recipient.
/// @param amount The amount that failed to transfer.
error TransferFailed(address to, uint256 amount);

